// The Kanban: every Tasks row by status. Behind the briefing's 🗂 Kanban button
// (menu-handler agent 'board') and the /board command.
//
//   /board              show the board, open cards numbered
//   /board add <text>   new card in To do
//   /board doing <n>    card n to Doing      /board done <n>   card n to Done
//
// A change goes out as `write` and Save Card upserts it on task_id. Rows that
// belong to commitments or upkeep can be moved too: done is done, whoever owns it.

const DONE_DAYS = 7;   // how long a finished card stays visible
const PER_COL   = 8;   // longer columns say how many were left out

const input = $('Called').first().json;
const today = String(input.date || $now.toFormat('yyyy-MM-dd')).slice(0, 10);
const since = new Date(Date.parse(today + 'T00:00:00Z') - DONE_DAYS * 864e5).toISOString().slice(0, 10);

const s  = (v) => String(v ?? '').trim();
const st = (r) => s(r.status).toLowerCase();
const rows = $('Get Tasks').all().map((i) => i.json).filter((r) => r && s(r.task_id));

// A bill that has not been charged yet is not a card yet.
const isLive = (r) => !s(r.charge_date) || s(r.charge_date).slice(0, 10) <= today;
const byDue  = (a, b) => (s(a.due_date) || '9').localeCompare(s(b.due_date) || '9')
  || s(a.task_id).localeCompare(s(b.task_id));
const isTodo = (r) => !['assigned', 'done', 'wont_fix', 'cancelled'].includes(st(r));

// Numbers follow the board as last shown: To do first, then Doing.
const open = [...rows.filter((r) => isLive(r) && isTodo(r)).sort(byDue),
              ...rows.filter((r) => isLive(r) && st(r) === 'assigned').sort(byDue)];

const card = (r) => {
  const what = s(r.vendor) ? s(r.vendor) + ' · ' + s(r.action) : s(r.action) || s(r.task_id);
  const due  = s(r.due_date) ? ' · due ' + s(r.due_date).slice(0, 10) : '';
  return what + due;
};
// ---- command ----------------------------------------------------------------
const cmd = s(input.text).match(/^(add|doing|done)\s+(.+)$/i);
let write = null;
let note  = '';
if (cmd) {
  const verb = cmd[1].toLowerCase();
  const arg  = cmd[2].trim();
  const now  = $now.toISO();
  if (verb === 'add') {
    const slug = arg.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 30) || 'card';
    write = { task_id: 'card::' + slug + '@' + today, action: arg, status: 'open',
              assignee: '', assigned_at: '', closed_at: '', source: 'board' };
    note = 'Added: ' + arg;
  } else {
    const r = open[Number(arg) - 1];
    if (!r) {
      note = 'No open card ' + arg + '.';
    } else {
      write = { task_id: s(r.task_id), action: s(r.action), source: s(r.source),
                status: verb === 'done' ? 'done' : 'assigned',
                assignee: s(r.assignee) || 'me',
                assigned_at: s(r.assigned_at) || now,
                closed_at: verb === 'done' ? now : '' };
      note = (verb === 'done' ? 'Done: ' : 'Doing: ') + card(r);
    }
  }
  if (write) {   // show the board as it will be after the write
    const i = rows.findIndex((r) => s(r.task_id) === write.task_id);
    if (i >= 0) rows[i] = { ...rows[i], ...write }; else rows.push(write);
  }
}

// ---- columns ----------------------------------------------------------------
const todo  = rows.filter((r) => isLive(r) && isTodo(r)).sort(byDue);
const doing = rows.filter((r) => isLive(r) && st(r) === 'assigned').sort(byDue);
const done  = rows.filter((r) => isLive(r) && st(r) === 'done' && s(r.closed_at).slice(0, 10) >= since);

let n = 0;
const numbered = (list) => list.map((r) => (++n) + '. ' + card(r));
const columns = [['To do', numbered(todo)], ['Doing', numbered(doing)], ['Done', done.map(card)]];
const blocks = columns
  .filter(([, items]) => items.length)
  .map(([heading, items]) => ({
    heading: heading + ' (' + items.length + ')',
    items: items.slice(0, PER_COL).concat(items.length > PER_COL ? ['… +' + (items.length - PER_COL) + ' more'] : []),
  }));

// Briefing plugin call: key 'board', plain-text section, no commands.
if (input.key === 'board') {
  return [{ json: { key: 'board', icon: '🗂', title: 'BOARD', blocks, empty: 'No cards' } }];
}

// Menu call: Send Reply there parses Markdown, so entity characters are replaced.
const md = (t) => String(t).replace(/[*_`\[]/g, '·');
const response = (note ? md(note) + '\n\n' : '') + '🗂 *Kanban*'
  + (blocks.length
    ? blocks.map((b) => '\n\n*' + md(b.heading) + '*' + b.items.map((i) => '\n  ' + md(i)).join('')).join('')
    : '\n\nNo cards')
  + '\n\n/board add <text> · /board doing <n> · /board done <n>';
return [{ json: { response, write } }];
